{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C23"],
      "claim": "Glycyrrhizin, a triterpenoid acid, has an absolute oral bioavailability of approximately 0.25% in humans; the query shares a large pentacyclic triterpenoid carboxylic acid scaffold, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Oleanolic acid, a pentacyclic triterpene acid, shows poor oral bioavailability in healthy volunteers with very low plasma AUC and Cmax after oral dosing; this is directly relevant to the triterpenoid acid character of the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "SRT2104, a complex synthetic molecule with high molecular weight and multiple polar groups, has an absolute oral bioavailability of 13.8% in humans, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Soticlestat has an absolute oral bioavailability of 12.6% in healthy volunteers, providing human evidence that complex heterocyclic molecules with multiple polar functionalities can fall below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Rilzabrutinib has a very low absolute oral bioavailability of 0.064 in humans, demonstrating that complex oral drugs with high clearance and polar features can have profoundly low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "DJ-927 is reported to have high oral bioavailability in patients, but it is a taxane with low structural similarity to the query and does not outweigh the consistent low-F evidence from closer analogues.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C13"],
      "claim": "CJ-13,610 showed about 47% oral bioavailability in humans, but it is a small, relatively lipophilic molecule with low transferability to the large triterpenoid-like query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C11"],
      "claim": "Alpelisib has 50–60% oral bioavailability in healthy subjects, but its small-molecule structure and favorable permeability properties are not representative of the query's large polar scaffold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a large pentacyclic triterpenoid-like carboxylic acid with multiple polar groups. The most transferable experimental evidence comes from triterpenoid acids (glycyrrhizin, oleanolic acid) and complex synthetic molecules (SRT2104, soticlestat, rilzabrutinib), all showing F <20% in humans. High-bioavailability examples are structurally distant small molecules or taxanes and do not outweigh the consistent low-F pattern. Therefore predict low oral bioavailability at the F >=20% threshold.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the query molecule.",
    "Morgan similarities to evidence molecules are low, limiting quantitative transferability.",
    "No data on solubility, permeability, efflux, or first-pass metabolism for the query.",
    "Formulation-dependent effects on oral absorption are unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

